/* @autogenerated */
import { computed, DestroyRef, Directive, inject, input, OnInit, Signal, signal, TemplateRef } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { TranslocoService } from '@jsverse/transloco';
import { combineLatest } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { Tick } from '@shared/data/repository/repository.model';
import { Action } from './action.model';
import type { ActionContainerComponent } from './action-container.component';

/** Lo mínimo que una acción necesita de su repositorio para resolver permisos. */
export interface AclSource {
  acl(): Tick<{ generic: Acl; specific?: Acl }, string | null>;
}

type ActionTexts = Partial<Record<string, string>>;

const HIDDEN = signal(false).asReadonly();
const ENABLED = signal(true).asReadonly();

const asTexts = (value: unknown): ActionTexts => (value && typeof value === 'object' ? (value as ActionTexts) : {});

/**
 * Base de las acciones: textos traducidos, ACL y valores por defecto de `Action`.
 *
 * Textos: `<scope>.action.<textKey>.*` con fallback a `common.action.<textKey>.*`.
 * Visibilidad: permiso `permission` en el ACL genérico del repositorio y `appliesTo(items)`.
 */
@Directive()
export abstract class BaseAction<T = any> implements Action, OnInit {
  abstract readonly name: string;
  readonly contextual: boolean = true;
  readonly multiple: boolean = false;
  readonly default = input<boolean>(false);

  /** Scope de transloco con los textos de la entidad. */
  protected abstract readonly scope: string;
  protected abstract readonly repository: AclSource;

  readonly container = signal<ActionContainerComponent | undefined>(undefined);
  selection: Signal<T[]> = signal<T[]>([]);
  readonly render: Signal<TemplateRef<any> | undefined> = signal(undefined);

  readonly label = computed(() => this.text('label'));
  readonly icon = computed(() => this.text('icon'));
  readonly tooltip = computed(() => this.text('tooltip'));
  readonly title = computed(() => this.text('title'));

  protected readonly destroyRef = inject(DestroyRef);
  private readonly transloco = inject(TranslocoService);
  private readonly scopedTexts = signal<ActionTexts>({});
  private readonly commonTexts = signal<ActionTexts>({});
  private readonly aclTick = signal<ReturnType<AclSource['acl']> | undefined>(undefined);
  private readonly permitted = computed(() => this.allowed());

  /** Clave de textos; por defecto el nombre en kebab-case (`deleteSelection` → `delete-selection`). */
  protected get textKey(): string {
    return this.name.replace(/[A-Z]/g, (char) => '-' + char.toLowerCase());
  }

  /** Permiso del ACL que hace visible la acción; por defecto su nombre. */
  protected get permission(): string {
    return this.name;
  }

  abstract run(): void;

  ngOnInit(): void {
    const acl = this.repository.acl();
    acl.fetch(null);
    this.aclTick.set(acl);
    combineLatest([
      this.transloco.selectTranslateObject(`action.${this.textKey}`, {}, this.scope),
      this.transloco.selectTranslateObject(`common.action.${this.textKey}`),
    ])
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(([scoped, common]) => {
        this.scopedTexts.set(asTexts(scoped));
        this.commonTexts.set(asTexts(common));
      });
  }

  visible(items: T[]): Signal<boolean> {
    return this.appliesTo(items) ? this.permitted : HIDDEN;
  }

  enabled(_items: T[]): Signal<boolean> {
    return ENABLED;
  }

  /** Condición sobre los elementos (p. ej. `enable` solo para los deshabilitados). */
  protected appliesTo(_items: T[]): boolean {
    return true;
  }

  protected allowed(name: string = this.permission): boolean {
    return !!this.aclTick()?.()?.generic?.allows?.find((allow) => allow.name == name)?.allowed;
  }

  protected text(field: string): string {
    return this.scopedTexts()[field] ?? this.commonTexts()[field] ?? '';
  }

  /** Clave completa de un texto (para pipes o servicios que traducen), o `undefined` si no existe. */
  protected textKeyOf(field: string): string | undefined {
    if (this.scopedTexts()[field]) {
      return `${this.scope}.action.${this.textKey}.${field}`;
    }
    if (this.commonTexts()[field]) {
      return `common.action.${this.textKey}.${field}`;
    }
    return undefined;
  }
}
